import Root from "./3Escape Hatches/2SynchronizingwithEffect"
import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useEffect, useRef, useState } from "react"

export default function() {
  const [online, setOnline] = useState("offline")
  function server() {
    return {
      connect() {setOnline("online")},
      disconnect() {setOnline("offline")}
    }
  }
  useEffect(() => {
    const connection = server()
  })
  return <>
  <p>{online}</p>
  </>
}


